    out.push({ key: 'hs_size_' + side.toLowerCase() + '_' + i, label: 'Hot Stamping Size (' + tag + ')', options: DLS_HS_SIZES, section: 'Optional Finishing', after: 'hot_stamping', showWhen: when });
