const HSM_PKG = { Normal: 'N', '2 in 1': '2', '3 in 1': '3', '4 in 1': '4', '5 in 1': '5', '6 in 1': '6', 'Dual Design': 'DD', '5 Design': '5D', '6 Design': '6D' };
const hsmPkg = cfg => cfg.mixdesign === 'Yes' ? (['Dual Design', '5 Design', '6 Design'].indexOf(cfg.package) >= 0 ? cfg.package : 'Dual Design') : (HSM_PKG[cfg.package] && !/Design/.test(cfg.package) ? cfg.package : 'Normal');
const hsmKey = cfg => { const p = { 'Gloss Art Paper 130gsm': 'GAP', 'Linen 140gsm': 'LIN', 'Art Paper 157gsm': 'AP' }[cfg.paper] || 'GAP';
  return HSM_PKG[hsmPkg(cfg)] + '|' + p + '|' + String(cfg.model || 'MP 101').replace(' ', '') + (p === 'AP' ? '|' + (cfg.lamination === 'Soft Touch Lamination' ? 'S' : 'M') : '') + '|' + (/Both/.test(cfg.finishing || '') ? 'B' : 'F'); };
const HSM_QTY = cfg => { const t = HSM_T[hsmKey(cfg)] || HSM_T[hsmKey(Object.assign({}, cfg, { mixdesign: 'No', package: 'Normal' }))] || []; return HSM_Q.filter((q, i) => t[i] != null); };
// packing per package (live list); Art Paper packs 5 or 6
const HSM_PACK = { 'Dual Design': ['6pcs / Pack', '8pcs / Pack', '10pcs / Pack'], '5 Design': ['5pcs / Pack', '10pcs / Pack'], '6 Design': ['6pcs / Pack'] };
const hsmPacking = cfg => { const all = HSM_PACK[hsmPkg(cfg)] || ['5pcs / Pack', '6pcs / Pack', '8pcs / Pack', '10pcs / Pack']; return cfg.paper === 'Art Paper 157gsm' ? all.filter(p => /^[56]pcs/.test(p)) : all; };
function hsmPriceBase(cfg, q) { const t = HSM_T[hsmKey(cfg)], i = HSM_Q.indexOf(q); return t && i >= 0 && t[i] != null ? t[i] : null; }

