const RF_PAPER = { 'White PP': [0.217, 0.01486], 'Transparent OPP': [0.813, 0.04435], 'Printing Paper': [-0.296, -0.02219], 'Synthetic Paper': [0.875, 0.0517], 'Hologram': [5.23, 0.27258] };
