function hsLpLL(pts, x) { const L = Math.log, n = pts.length; if (x <= pts[0][0]) return pts[0][1];
  if (x >= pts[n - 1][0]) { if (n < 2) return pts[0][1]; const [a, ya] = pts[n - 2], [b, yb] = pts[n - 1]; return Math.exp(L(yb) + (L(yb) - L(ya)) / (L(b) - L(a)) * (L(x) - L(b))); }
  for (let i = 1; i < n; i++) if (x <= pts[i][0]) { const [a, ya] = pts[i - 1], [b, yb] = pts[i]; return Math.exp(L(ya) + (L(yb) - L(ya)) * (L(x) - L(a)) / (L(b) - L(a))); } }
