const stkFit = (L, a, g) => Math.floor((L + g) / (a + g));
const stkUps = (A, B, g) => (h, w) => Math.max(stkFit(A, h, g) * stkFit(B, w, g), stkFit(A, w, g) * stkFit(B, h, g));
