// Cut To Size, rebuilt 23 Oct from a 550-quote live grid (Mirror Kote 50-300 mm x 100-50,000 pcs): Excard packs a 320 x 452 mm area
// with a 2 mm gap, grid plus a rotated strip in the leftover space, then charges a per-sheet curve + RM0.01 a sticker (2.8% mean)
const stkMixed = (A, B, g) => (h, w) => { let best = 0; for (const [x, y] of [[h, w], [w, h]]) { const nx = stkFit(A, x, g), ny = stkFit(B, y, g);
  for (let k = 0; k <= nx; k++) best = Math.max(best, k * stkFit(B, y, g) + stkFit(A - k * (x + g), y, g) * stkFit(B, x, g));
  for (let k = 0; k <= ny; k++) best = Math.max(best, k * stkFit(A, x, g) + stkFit(B - k * (y + g), x, g) * stkFit(A, y, g)); } return best; };
