const stkAtLog = (F, s) => { const ls = Math.log(Math.max(1, s)); let i = 0; while (i < F.length - 2 && Math.log(F[i + 1][0]) < ls) i++;
  const t = (ls - Math.log(F[i][0])) / (Math.log(F[i + 1][0]) - Math.log(F[i][0])); return Math.exp(Math.log(F[i][1]) + (Math.log(F[i + 1][1]) - Math.log(F[i][1])) * t); };
const stkAt = (F, s) => { if (s <= F[0][0]) return F[0][1]; for (let i = 1; i < F.length; i++) if (s <= F[i][0]) { const [a, pa] = F[i - 1], [b, pb] = F[i]; return pa + (pb - pa) * (s - a) / (b - a); }
  const [a, pa] = F[F.length - 2], [b, pb] = F[F.length - 1]; return pb + (pb - pa) * (s - b) / (b - a); };
