function stkDieRE(h, w, q) { const u = STK_UPS_DIE3(h, w); if (!(u > 0)) return null; const s = Math.ceil(q / u); if (s <= 80) return null;
  let t = 5; for (let i = 1; i < STK_DIE_RT.length; i++) if (s <= STK_DIE_RT[i]) { t = i - 1; break; } const F = STK_DIE_RF;
  const base = 1.21 * (F[t] * s + F[6] + q * (F[8] + F[9] * (h + w) / 100 + F[10] * h * w / 1e4));
  const a = Math.min(h, w), b = Math.max(h, w), D = STK_DIE_D, L = Math.log, br = x => { let i = 0; while (i < D.length - 2 && D[i + 1] < x) i++; return [D[i], D[i + 1], Math.max(0, Math.min(1, (L(x) - L(D[i])) / (L(D[i + 1]) - L(D[i]))))]; };
  const [a1, a2, ta] = br(a), [b1, b2, tb] = br(b); let sl = 0, ws = 0, exact = false;
  for (const [x, y, wt] of [[a1, b1, (1 - ta) * (1 - tb)], [a2, b1, ta * (1 - tb)], [a1, b2, (1 - ta) * tb], [a2, b2, ta * tb]]) { if (wt <= 0) continue; const c = STK_DIE_RC[x + 'x' + y]; if (!c) continue; if (wt > 0.9999) exact = true; sl += wt * L(stkLog(c, q)); ws += wt; }
  return base * (ws ? Math.exp((exact ? 1 : 0.75) * sl / ws) : 1); }
function stkDieMK(h, w, q) { const u = STK_UPS_DIE2(h, w); if (!(u > 0)) return null; const re = stkDieRE(h, w, q); if (re != null) return re;
  const a = Math.min(h, w), b = Math.max(h, w), D = STK_DIE_D, L = Math.log;
  const br = x => { let i = 0; while (i < D.length - 2 && D[i + 1] < x) i++; return [D[i], D[i + 1], Math.max(0, Math.min(1, (L(x) - L(D[i])) / (L(D[i + 1]) - L(D[i]))))]; };
  const [a1, a2, ta] = br(a), [b1, b2, tb] = br(b); let sl = 0, ws = 0;
  for (const [x, y, wt] of [[a1, b1, (1 - ta) * (1 - tb)], [a2, b1, ta * (1 - tb)], [a1, b2, (1 - ta) * tb], [a2, b2, ta * tb]]) {
    const R = STK_DIE_R[Math.min(x, y) + 'x' + Math.max(x, y)]; if (wt <= 0 || !R) continue; sl += wt * L(stkLog(R, q)); ws += wt; }
  return ws ? (stkFC2(Math.ceil(q / u)) + 0.01 * q) * Math.exp(sl / ws) : null; }
