// one consistent style for every configurator question label: Title Case, acronyms and codes
// kept (UV, DTF, 4C…), units kept lowercase (mm, gsm…), raw data keys given friendly names
const LABEL_NAMES = { size: 'Size', paper: 'Paper', colour: 'Print Colour', lamination: 'Lamination', category: 'Category', model: 'Model', sleeve: 'Sleeve', fabric: 'Fabric', uvdtfstickering: 'UV DTF Stickering' };
const LABEL_KEEP = { UV: 1, DTF: 1, VDP: 1, NCR: 1, PVC: 1, PP: 1, PET: 1, OPP: 1, QR: 1, ID: 1, A1: 1, A2: 1, A3: 1, A4: 1, A5: 1, A6: 1, A7: 1, B5: 1, DL: 1, RM: 1, '1C': 1, '2C': 1, '4C': 1, CMYK: 1, RGB: 1 };
const LABEL_LOWER = { mm: 1, cm: 1, gsm: 1, pcs: 1, pc: 1, kg: 1, g: 1, micron: 1 };
const LABEL_SMALL = { of: 1, and: 1, or: 1, per: 1, to: 1, a: 1, an: 1, the: 1, in: 1, on: 1, with: 1, for: 1, at: 1, by: 1, x: 1 };
function niceLabel(raw, key) {
  const k = String(key || '').toLowerCase();
  let s = String(raw == null || raw === '' ? key || '' : raw).trim();
  // (user, 2026-09-30) internal qualifiers stay internal: "(block quoted separately)", "— Rectangle/Standard/Custom",
  // "— Multiple Dieline only", "(no price effect)", "(Sticker only)", "— Round only"
  s = s.replace(/\s*\([^)]*quoted separately\)/ig, '').replace(/\s*\((no price effect|sticker only)\)/ig, '')
    .replace(/\s*[—–-]\s*(rectangle\/standard\/custom|standard shape|round only|multiple dieline( only)?)\b.*$/i, '').trim();
  if (LABEL_NAMES[k] && (!raw || String(raw).toLowerCase() === k || String(raw) === String(raw).toLowerCase() || String(raw) === String(raw).toUpperCase())) return LABEL_NAMES[k];
  if (/_/.test(s)) s = s.replace(/_/g, ' ');
  let i = 0;
  const word = w => {
    const first = i++ === 0, up = w.toUpperCase(), lo = w.toLowerCase();
    if (LABEL_KEEP[up]) return up;
    if (LABEL_LOWER[lo]) return lo;
    if (!first && LABEL_SMALL[lo]) return lo;
    if (w === up && w.length > 3) return w.charAt(0) + lo.slice(1); // SHOUTED word → Title
    return w.charAt(0).toUpperCase() + w.slice(1);
  };
  // only the label itself is Title Cased — bracketed qualifiers like (mm) or (price-neutral) stay as written
  return s.replace(/\([^)]*\)|[^()]+/g, seg => seg.charAt(0) === '(' ? seg : seg.replace(/[A-Za-z][A-Za-z0-9'’.-]*|\d+[A-Za-z]+/g, word));
}
// option text as shown: "- Not Required -" reads as "Not Required" like every other question
// (user, 2026-09-29) the N-in-1 package reads as artworks: "2 In 1 (2 Designs)" / "2in1" → "2 artworks",
// "2 IN 1 (5% Off)" → "2 artworks (5% Off)", "Normal (1 Design)" → "Normal". Display only — the priced value is unchanged.
const cleanOpt = v => {
  // (user, 2026-09-30) "Rectangle/Square" reads "Rectangle / Square" so it can wrap, and the "(2 side coated)"
  // bracket is dropped everywhere it is shown (display only — the priced value is unchanged)
  const s = String(v == null ? '' : v).replace(/^-\s*(.*?)\s*-$/, '$1').trim().replace(/([A-Za-z])\/([A-Za-z])/g, '$1 / $2').replace(/\s*\(2 sides? coated\)/i, '');
  const m = s.match(/^(\d+)\s*in\s*1\b\s*(?:\(\d+\s*designs?\))?\s*(.*)$/i);
  if (m) return m[1] + ' artworks' + (m[2] ? ' ' + m[2] : '');
  return /^normal \(1 design\)$/i.test(s) ? 'Normal' : s;
};
// (user, 2026-09-30) book configurator wording: 4C reads "Colourful", 1C "Single Colour" (display only)
const bookOptLabel = (t, isPrint) => !isPrint ? t : String(t).replace(/\b4\s*C\b/g, 'Colourful').replace(/\b1\s*C\b/g, 'Single Colour').replace(/\b2\s*C\b/g, 'Two Colours');
// a short plain-English line under each material: finish + how thick it feels
const matDesc = v => { const t = String(v || ''), g = +((t.match(/(\d{2,3})\s*gsm/i) || [])[1] || 0);
  const fin = /gloss/i.test(t) ? 'Shiny finish, vivid colours' : /matt/i.test(t) ? 'Smooth, no-glare finish' : /kraft/i.test(t) ? 'Natural brown, eco look' : /synthetic|pvc|plastic|yupo|polyester|vinyl/i.test(t) ? 'Waterproof and tear-resistant' : /linen|texture|felt|canvas/i.test(t) ? 'Textured, premium feel' : /pearl|metallic|shimmer/i.test(t) ? 'Shimmering premium finish' : /simili|woodfree|uncoated|bond/i.test(t) ? 'Natural feel, easy to write on' : '';
  const wt = !g ? '' : g <= 120 ? 'light, like office paper' : g <= 170 ? 'flyer weight' : g <= 260 ? 'firm card' : g <= 330 ? 'thick card' : 'extra-thick premium card';
  return [fin, wt].filter(Boolean).join(' · ') || null; };
// an option that means "this finishing / add-on is not applied" (Excard's optional questions)
const OPT_NONE_RE = /^(-\s*)?(not required|no required|none|n\/a|not applicable|no [a-z ]+|without [a-z ]+|no|0)(\s*-)?$/i;
const isNoneOpt = o => OPT_NONE_RE.test(String(Array.isArray(o) ? o[0] : o).trim());
